INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(2607, 'koKR', 'Dotyk Zanzila', 'Wygląda na to, że $gprzyniosłeś:przyniosłaś; więcej informacji, niż nawet ja się spodziewałem. To doprawdy dziwny obrót spraw, $N.$B$BLekarstwo? Hmm... Zejdź do piwnicy i porozmawiaj z doktorem Mixilpixilem – może on zdoła pomóc.', 'Porozmawiaj z doktorem Mixilpixilem w piwnicy koszar.', '', '', '', '', '', '', 0),
(2608, 'koKR', 'Dotyk Zanzila', 'O rety, wyglądasz jak śmierć. Poprawka – widziałem śmierć, a ty wyglądasz gorzej. $GSzanowny panie:Panienko;, jesteś tym, co śmierć wykaszlała na ostatnim badaniu okresowym.$B$BHa! Słyszałeś, Noarm? Zapisz to sobie!$B$B*Kaszel* Hmm, tak, żeby ci pomóc, muszę pobrać trochę krwi. Nie martw się, boli tylko przez pierwsze... pięćdziesiąt razy czy coś koło tego... Gdy będziesz $ggotów:gotowa; na zabieg, połóż się na ziemi (/lay), $N.', 'Połóż się (/lay), żeby doktor Mixilpixil mógł cię zbadać. Jak ma znaleźć lekarstwo, jeśli nie znajdzie przyczyny?$B', 'Diagnoza zakończona', 'Wróć do doktora Mixilpixila w Wichrogrodzie.', '', '', '', '', 0),
(2609, 'koKR', 'Dotyk Zanzila', 'Jednogłośnie, $N. Masz „itis”.$B$BNa szczęście mam lekarstwo na „itis”.$B$BOto czego potrzebuję: jednego pęczka prostych polnych kwiatów, jednej ołowianej fiolki, jednej brązowej rury i wreszcie, co nie mniej ważne, jednej szpuli jasnej seledynowej nici jedwabnej. Stara Emma zostawiła mi szpulę w sklepie „Najlepsza Nić”. Znajdziesz go przy kanałach.$B$BPośpiesz się, $N, i postaraj się nikogo nie dotykać, dopóki cię nie wyleczę. A, i doktor Montgomery mówi, że musisz się umyć – to jego słowa, nie moje.', 'Przynieś doktorowi Mixilpixilowi jeden pęczek prostych polnych kwiatów, jedną ołowianą fiolkę, jedną brązową rurę i jedną szpulę jasnej seledynowej nici jedwabnej. „Itis” sam się nie wyleczy, $gmłodzieńcze:panienko;.', '', 'Wróć do doktora Mixilpixila w Dolinie Bohaterów w Wichrogrodzie.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(2607, 'koKR', 'Najwyższy czas! Połóż ser na stole i zmykaj. Osborne zapłaci ci przy wyjściu.', 0),
(2608, 'koKR', 'Daj mi chwilę na konsultację z kolegami, $N. Doktorze Montgomery, panie Noarm, naradźmy się!', 0),
(2609, 'koKR', 'Co robię? A na co to wygląda? Wymyślam lekarstwo na twój „itis”! Tylko się teraz nie oburzaj, $N!$b$bJeszcze kilka sekund. Gotowe! Spryskaj się tym, eee, fantastycznie pachnącym lekarstwem, a będziesz jak $gnowy:nowa;.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(2608, 'koKR', 'Gdy będziesz $ggotów:gotowa; na badanie, połóż się na ziemi (/lay), a zacznę upuszczać krew.', 0),
(2609, 'koKR', 'Jeśli chcesz wyleczyć „itis”, musisz się bardziej postarać, $n. Gdzie są składniki na lekarstwo?', 0);
