INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(2867, 'koKR', 'Bractwo nie pozwoli, by przeszkadzały mu insekty.', '', 0),
(3411, 'koKR', 'Mów cicho i ostrożnie – jedno złe słowo w tych stronach może cię kosztować poderżnięte gardło. No więc, czego ode mnie chcesz?', 'Mów cicho i ostrożnie – jedno złe słowo w tych stronach może cię kosztować poderżnięte gardło. No więc, czego ode mnie chcesz?', 0),
(3563, 'koKR', '%s przygotowuje strzykawkę.', '', 0),
(3564, 'koKR', '%s ogląda krew w fiolce.', '', 0),
(3565, 'koKR', 'Bardzo interesujące!', '', 0),
(3566, 'koKR', '%s zdaje się rozmawiać z wiewiórką i posągiem. Co jakiś czas wskazuje na ciebie.', '', 0),
(3567, 'koKR', 'Po prostu połóż się gdziekolwiek (/lay), $n. Obiecuję, że nic nie poczujesz!', '', 0),
(3568, 'koKR', 'To nie wygląda dobrze!', '', 0),
(45290, 'koKR', 'W czym mogę pomóc?', '', 0);
